/*
 * Modified by Actuna Sp. z o.o.:
 *   E-02: new module - the state of the instance (process life cycle and the
 *   state of the flows), event instance:state
 *   #1 (R-47): the condition `reload` (a failed reload from storage), next to
 *   the state; a change of it emits instance:state even when `state` is the same
 *   #76: a listener that throws any value (also one that cannot be printed) is logged as one
 *   warning (printable.js); the other listeners and instance:state are not skipped
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

/**
 * The state of the instance (E-02): one authoritative state of the process
 * life cycle and of the flows, read by the health probes (Z-08) and - later -
 * by reloads from storage (Z-09), coordination (Z-10) and editor-only
 * instances (Z-15).
 *
 * The module is passive: it does not change any response, log message or
 * event of the runtime. The state is set by explicit calls from the runtime
 * (runtime start/stop, the deploy pipeline, `POST /flows/state`, the start of
 * the flows); the `flows:*` events are not used, as they are emitted also
 * during deployments and after a failed `Flow.start`.
 *
 * Every change emits `instance:state` on the runtime events (`RED.events`)
 * with a copy of {@link StateInfo} - the fields `state`, `previous` and
 * `reason` are the contract (R-23), the others are additive.
 *
 * The condition `reload` (R-47) is a fact next to the state, not a state: the
 * reload from storage failed (the retries were exhausted) and the instance may
 * still run the previous revision. It is set by `markReloadFailed(info)` and
 * cleared by `clearReloadFailed()` (the module does not read settings - the
 * policy is that of the caller and of the health probes). The R-23 transitions
 * are not affected. A change of the condition emits `instance:state` also when
 * `state` does not change (a new rule of the contract R-23: a listener that
 * reacts only to state changes compares `state`, `reason` and `since`); the
 * event carries a copy of the condition in `reload` - only while it is set.
 *
 * States:
 *
 * | state           | meaning                                                    |
 * |-----------------|------------------------------------------------------------|
 * | `init`          | initial state - until `runtime.start()` is called          |
 * | `starting`      | from `runtime.start()` until the first start of the flows  |
 * | `ready`         | the flows run, the last operation completed without errors |
 * | `deploying`     | a deployment (deploy pipeline step 4 to step 8)            |
 * | `reloadPending` | a reload from storage is pending (no lock, no token);      |
 * |                 | `draining: true` from the call of `preReload`              |
 * | `reloading`     | a reload from storage under the deploy lock                |
 * | `idle`          | the flows are stopped (`runtimeFlowState: stop`, safe mode)|
 * | `loaded`        | editor-only instance: the flows are loaded, not started    |
 * | `failed`        | the start of the flows failed                              |
 * | `stopping`      | from the call of `runtime.stop()` or a stop signal - final |
 * | `stopped`       | after `runtime.stop()` completed - final                   |
 *
 * Transitions (the table {@link TRANSITIONS} is the source of truth; the ids
 * are those of the E-02 card):
 *
 * | #   | from                                  | to                                 | call                       |
 * |-----|---------------------------------------|------------------------------------|----------------------------|
 * | T1  | init                                  | starting                           | markStarting()             |
 * | T2  | starting                              | ready                              | report(result)             |
 * | T3  | starting                              | failed                             | report(result) / fail()    |
 * | T4  | starting                              | idle                               | report(result)             |
 * | T5  | ready, failed, idle, loaded,          | deploying                          | begin("deploy")            |
 * |     | reloadPending (cancels the reload)    |                                    |                            |
 * | T6  | deploying                             | ready, failed, idle, loaded        | end(token, result)         |
 * | T7  | ready, failed, idle, loaded           | reloadPending                      | markReloadPending(info)    |
 * | T7a | reloadPending                         | reloadPending (draining)           | markDraining()             |
 * | T7b | reloadPending                         | the state before T7                | cancelPending(reason)      |
 * | T8  | reloadPending                         | reloading                          | begin("reload")            |
 * | T8a | reloading                             | ready, failed, idle, loaded        | end(token, result)         |
 * |     |                                       | (aborted: the state before T7)     |                            |
 * | T9  | failed                                | ready                              | report(result) (late start)|
 * | T10 | idle                                  | ready                              | begin/end("set-state")     |
 * | T11 | ready, failed                         | idle                               | begin/end("set-state")     |
 * | T12 | any but stopping, stopped             | stopping                           | markStopping(reason)       |
 * | T13 | stopping                              | stopped                            | markStopped(err)           |
 * | T14 | starting                              | loaded                             | report(result) editor-only |
 *
 * Additional transitions not numbered on the card: a deployment while the
 * runtime is still starting (`starting` → `deploying`), and the result of a
 * start outside an operation (project switch, late start) from any resting
 * state (`ready`, `failed`, `idle`) to another one.
 * @module
 */

const { events, log } = require("@node-red/util");
const { messageText } = require("./printable");

/**
 * @typedef {"init"|"starting"|"ready"|"deploying"|"reloadPending"|"reloading"|"idle"|"loaded"|"failed"|"stopping"|"stopped"} InstanceState
 */
/**
 * @typedef StateInfo
 * @type {object}
 * @property {InstanceState} state
 * @property {InstanceState|null} previous
 * @property {string} reason - for example "startup", "deploy", "reload", "set-state",
 *     "missing-types", "missing-modules", "flow-start-failed", "storage-error",
 *     "safe-mode", "stop", "SIGTERM"
 * @property {number} since - Date.now() when the state was entered
 * @property {boolean} [draining] - only in "reloadPending": true from the call of preReload
 * @property {Array<{code: string, message: string}>} [errors] - only in "failed"
 * @property {ReloadCondition} [reload] - only while the condition is set
 */
/**
 * @typedef ReloadCondition
 * @type {object}
 * @property {{code: string}} error - `storage_error`, `credentials_load_failed`, `invalid_flows`, ...
 * @property {number} since - Date.now() when the condition was set (kept while it lasts)
 * @property {number} attempts - failed reads of storage so far
 * @property {string|null} activeRev - the running revision
 * @property {string|null} rev - the revision in storage the instance could not load, when known
 * @property {boolean} keepReady - the instance stays ready on the running revision
 *     (`deploy.reload.retry.onExhausted: "keepReady"`)
 * @property {number|null} staleDeadline - Date.now() after which `/ready` is 503
 *     (`since` + `maxStaleTime`), null without a limit
 * @property {boolean} [stale] - true once `staleDeadline` has passed (set by the timer of the reloader)
 */

const STATES = ["init", "starting", "ready", "deploying", "reloadPending", "reloading", "idle", "loaded", "failed", "stopping", "stopped"];

/**
 * The allowed transitions `{from: [to, ...]}`. A state may always be entered
 * again from itself (a new reason); `stopping` and `stopped` are final.
 */
const TRANSITIONS = {
    init: ["starting", "stopping"],
    starting: ["ready", "failed", "idle", "loaded", "deploying", "stopping"],
    ready: ["deploying", "reloadPending", "failed", "idle", "stopping"],
    failed: ["deploying", "reloadPending", "ready", "idle", "stopping"],
    idle: ["deploying", "reloadPending", "ready", "failed", "stopping"],
    loaded: ["deploying", "reloadPending", "stopping"],
    deploying: ["ready", "failed", "idle", "loaded", "stopping"],
    reloadPending: ["deploying", "reloading", "ready", "failed", "idle", "loaded", "stopping"],
    reloading: ["ready", "failed", "idle", "loaded", "stopping"],
    stopping: ["stopped"],
    stopped: []
};

const OPERATIONS = ["deploy", "reload", "set-state"];

// The resting states a pending reload can start from and return to
const RESTING = ["ready", "failed", "idle", "loaded"];

let current;
// The operation under the deploy lock: {token, operation, restore} or null
let active;
// The state before markReloadPending(): {state, reason, errors} or null
let pending;
// Set once the instance entered "loaded" (editor-only): never "ready" afterwards
let editorOnly;
let listeners = [];
// The condition of a failed reload from storage (R-47) or null
let reloadCondition = null;

function initialState() {
    return { state: "init", previous: null, reason: "init", since: Date.now() };
}

function snapshot(info) {
    const copy = { state: info.state, previous: info.previous, reason: info.reason, since: info.since };
    if (info.state === "reloadPending") {
        copy.draining = !!info.draining;
    }
    if (info.state === "failed" && info.errors) {
        copy.errors = info.errors.map(function(e) { return Object.assign({}, e) });
    }
    if (reloadCondition) {
        copy.reload = copyCondition(reloadCondition);
    }
    return copy;
}

function copyCondition(condition) {
    const copy = Object.assign({}, condition);
    copy.error = Object.assign({}, condition.error);
    return copy;
}

function sameCondition(a, b) {
    const keys = Object.keys(a).concat(Object.keys(b));
    return keys.every(function(key) {
        if (key === "error") {
            return a.error.code === b.error.code;
        }
        return a[key] === b[key];
    });
}

function notify() {
    const info = snapshot(current);
    for (const listener of listeners.slice()) {
        try {
            listener(snapshot(info));
        } catch (err) {
            log.warn("instance state listener failed: " + messageText(err));
        }
    }
    events.emit("instance:state", info);
}

function isAllowed(from, to) {
    return from === to || TRANSITIONS[from].indexOf(to) !== -1;
}

/**
 * Moves to `state`. Returns false (and logs at trace level) when the
 * transition is not allowed. No event when the state, the reason and the
 * draining flag do not change.
 */
function transition(state, reason, extra) {
    extra = extra || {};
    if (!isAllowed(current.state, state)) {
        log.trace("instance state: ignored transition " + current.state + " -> " + state + " (" + reason + ")");
        return false;
    }
    if (state === "loaded") {
        editorOnly = true;
    }
    const draining = state === "reloadPending" ? !!extra.draining : undefined;
    if (state === current.state && reason === current.reason && draining === current.draining) {
        if (state === "failed") {
            current.errors = extra.errors || current.errors;
        }
        return true;
    }
    const next = {
        state: state,
        previous: state === current.state ? current.previous : current.state,
        reason: reason,
        since: Date.now()
    };
    if (state === "reloadPending") {
        next.draining = draining;
    }
    if (state === "failed") {
        next.errors = extra.errors || [];
    }
    current = next;
    notify();
    return true;
}

function isFinal() {
    return current.state === "stopping" || current.state === "stopped";
}

function toErrors(errors, code) {
    if (!errors) {
        return [{ code: code, message: code }];
    }
    const list = Array.isArray(errors) ? errors : [errors];
    return list.map(function(e) {
        if (e && typeof e === "object") {
            return { code: e.code || code, message: e.message || String(e.code || code) };
        }
        return { code: code, message: String(e) };
    });
}

/**
 * Maps the result of a start of the flows (E-01 `{errors}`, extended with
 * `flowsRunning` and `reason`) to the resting state.
 * @param {{errors?: Array, flowsRunning?: boolean, reason?: string}} result
 * @param {string} reason - the reason when the flows run
 * @return {{state: InstanceState, reason: string, errors?: Array}}
 */
function outcome(result, reason) {
    result = result || {};
    const errors = result.errors || [];
    if (result.flowsRunning === false) {
        if (result.reason === "editor-only" || editorOnly) {
            return { state: "loaded", reason: result.reason || reason };
        }
        return { state: "idle", reason: result.reason || reason };
    }
    if (errors.length > 0) {
        return { state: "failed", reason: String(errors[0].code || "flow_start_failed").replace(/_/g, "-"), errors: toErrors(errors, "flow_start_failed") };
    }
    if (editorOnly) {
        return { state: "loaded", reason: reason };
    }
    return { state: "ready", reason: reason };
}

/**
 * @return {StateInfo} a copy of the current state (no I/O, O(1))
 */
function get() {
    return snapshot(current);
}

/**
 * @return {boolean} true in "ready" and "loaded" (D-13), and in "reloadPending"
 *     before draining when the state before it was ready; false otherwise
 */
function isReady() {
    if (current.state === "ready" || current.state === "loaded") {
        return true;
    }
    if (current.state === "reloadPending" && !current.draining && pending) {
        return pending.state === "ready" || pending.state === "loaded";
    }
    return false;
}

/**
 * @param {function(StateInfo)} listener - called on every change; an exception
 *     is logged as a warning and the other listeners are still called
 * @return {function()} unsubscribes the listener
 */
function onChange(listener) {
    listeners.push(listener);
    return function() {
        listeners = listeners.filter(function(l) { return l !== listener });
    };
}

/**
 * T1: `runtime.start()` was called.
 */
function markStarting() {
    transition("starting", "startup");
}

/**
 * Starts an operation under the deploy lock (T5, T8, T10/T11). Called only
 * inside the deploy lock (flows/lock.js).
 * @param {"deploy"|"reload"|"set-state"} operation
 * @param {object} [info]
 * @param {boolean} [info.supersede] - replace a running operation instead of
 *     throwing: used by the runtime when the lock was released before the start
 *     of the previous operation completed (`deploy.startTimeoutReleasesLock`, R-45)
 * @return {symbol|null} the token of the operation, or null in "stopping"/"stopped"
 * @throws {Error} code `state_operation_in_progress` when another operation runs
 */
function begin(operation, info) {
    if (OPERATIONS.indexOf(operation) === -1) {
        throw new Error("Unknown operation: " + operation);
    }
    if (isFinal()) {
        log.trace("instance state: ignored begin(" + operation + ") in " + current.state);
        return null;
    }
    if (active && !(info && info.supersede)) {
        const err = new Error("Operation in progress: " + active.operation);
        err.code = "state_operation_in_progress";
        err.status = 409;
        throw err;
    }
    let restore = { state: current.state, reason: current.reason, errors: current.errors };
    if (active) {
        restore = active.restore;
    }
    if (current.state === "reloadPending") {
        restore = pending;
    }
    const token = Symbol(operation);
    if (operation === "deploy") {
        transition("deploying", "deploy");
    } else if (operation === "reload") {
        // Only from "reloadPending" (T8); elsewhere the transition is ignored
        transition("reloading", "reload");
    }
    // "set-state" keeps the state until end()
    pending = null;
    active = { token: token, operation: operation, restore: restore };
    return token;
}

/**
 * Ends an operation (T6, T8a, T10, T11). A stale token (another operation, or
 * after "stopping") is ignored.
 * @param {symbol} token
 * @param {{errors?: Array, flowsRunning?: boolean, reason?: string, aborted?: boolean}} result
 *     `aborted` - the operation did not change the flows: back to the state before it
 */
function end(token, result) {
    if (!active || !token || active.token !== token) {
        log.trace("instance state: ignored end() with a stale token");
        return;
    }
    const operation = active.operation;
    const restore = active.restore;
    active = null;
    result = result || {};
    if (result.aborted) {
        transition(restore.state, restore.reason, { errors: restore.errors });
        return;
    }
    const next = outcome(result, operation);
    transition(next.state, next.reason, next);
}

/**
 * The result of a start of the flows outside an operation: the first start
 * (T2, T3, T4, T14), a late start after a missing type was registered (T9) or
 * a project switch. Ignored while an operation runs (its end() sets the state),
 * in "init" and in "stopping"/"stopped".
 * @param {{errors?: Array, flowsRunning?: boolean, reason?: string}} result
 */
function report(result) {
    if (active || current.state === "init" || isFinal() || current.state === "reloadPending") {
        return;
    }
    const next = outcome(result, current.state === "starting" ? "startup" : "start");
    transition(next.state, next.reason, next);
}

/**
 * T3: the start failed outside an operation (the flows could not be read
 * from storage, the start was rejected). Ignored while an operation runs.
 * @param {Error|Array} errors
 * @param {string} [reason="startup-error"]
 */
function fail(errors, reason) {
    if (active || current.state === "init" || isFinal()) {
        log.trace("instance state: ignored fail() in " + current.state);
        return;
    }
    reason = reason || "startup-error";
    transition("failed", reason, { errors: toErrors(errors, reason.replace(/-/g, "_")) });
}

/**
 * T7 (Z-09): a reload from storage is pending - no lock and no token.
 * @param {object} [info]
 * @param {string} [info.reason="reload"]
 * @return {boolean} whether the state changed to "reloadPending"
 */
function markReloadPending(info) {
    if (active || RESTING.indexOf(current.state) === -1) {
        log.trace("instance state: ignored markReloadPending() in " + current.state);
        return false;
    }
    pending = { state: current.state, reason: current.reason, errors: current.errors };
    return transition("reloadPending", (info && info.reason) || "reload", { draining: false });
}

/**
 * T7a (Z-09): the pending reload starts draining (preReload called) - `/ready` 503.
 * @return {boolean}
 */
function markDraining() {
    if (current.state !== "reloadPending") {
        return false;
    }
    return transition("reloadPending", current.reason, { draining: true });
}

/**
 * T7b (Z-09): the pending reload is cancelled - back to the state before it.
 * @param {string} [reason]
 * @return {boolean}
 */
function cancelPending(reason) {
    if (current.state !== "reloadPending" || !pending) {
        return false;
    }
    const restore = pending;
    pending = null;
    return transition(restore.state, reason || restore.reason, { errors: restore.errors });
}

/**
 * T12: the runtime is stopping - final. Idempotent.
 * @param {string} [reason="stop"]
 * @return {boolean} whether the state changed
 */
function markStopping(reason) {
    if (isFinal()) {
        return false;
    }
    active = null;
    pending = null;
    return transition("stopping", reason || "stop");
}

/**
 * T13: `runtime.stop()` completed (also when it failed).
 * @param {Error} [err]
 */
function markStopped(err) {
    if (current.state !== "stopping") {
        return;
    }
    transition("stopped", current.reason, err ? { errors: toErrors(err, "stop_failed") } : undefined);
}

/**
 * R-47: the reload from storage failed (the retries were exhausted). Sets or
 * updates the condition `reload`; the state is not changed. `instance:state`
 * is emitted when the condition changes. Ignored in "stopping" and "stopped".
 * @param {object} info
 * @param {string|{code: string}} info.error - the code of the error
 * @param {number} [info.since] - the start of the condition; kept from the
 *     running condition, Date.now() for a new one
 * @param {number} [info.attempts=0]
 * @param {string|null} [info.activeRev=null]
 * @param {string|null} [info.rev=null]
 * @param {boolean} [info.keepReady=false]
 * @param {number|null} [info.staleDeadline=null]
 * @param {boolean} [info.stale] - only set when true
 * @return {boolean} whether the condition changed
 */
function markReloadFailed(info) {
    if (isFinal()) {
        log.trace("instance state: ignored markReloadFailed() in " + current.state);
        return false;
    }
    info = info || {};
    const code = (info.error && typeof info.error === "object") ? info.error.code : info.error;
    const next = {
        error: { code: String(code || "storage_error") },
        since: reloadCondition ? reloadCondition.since : (info.since !== undefined ? info.since : Date.now()),
        attempts: info.attempts || 0,
        activeRev: info.activeRev === undefined ? null : info.activeRev,
        rev: info.rev === undefined ? null : info.rev,
        keepReady: info.keepReady === true,
        staleDeadline: typeof info.staleDeadline === "number" ? info.staleDeadline : null
    };
    if (info.stale === true) {
        next.stale = true;
    }
    if (reloadCondition && sameCondition(reloadCondition, next)) {
        return false;
    }
    reloadCondition = next;
    notify();
    return true;
}

/**
 * R-47: the condition `reload` is over (storage was read, a reload or a
 * deployment succeeded). `instance:state` is emitted when it was set.
 * @return {boolean} whether the condition was set
 */
function clearReloadFailed() {
    if (!reloadCondition) {
        return false;
    }
    reloadCondition = null;
    notify();
    return true;
}

/**
 * Resets the module to "init" (tests only).
 */
function reset() {
    current = initialState();
    reloadCondition = null;
    active = null;
    pending = null;
    editorOnly = false;
    listeners = [];
}

reset();

module.exports = {
    STATES,
    TRANSITIONS,
    get,
    isReady,
    onChange,
    markStarting,
    begin,
    end,
    report,
    fail,
    markReloadPending,
    markDraining,
    cancelPending,
    markReloadFailed,
    clearReloadFailed,
    markStopping,
    markStopped,
    reset
};
